function setup() {
  createCanvas(700, 500);
  noiseDetail(8, 0.25);
  // noLoop() removed for animation
}

function mousePressed() {

  redraw();
}

function keyPressed() {
  save();
}

function draw() {
  noiseSeed(random(Number.MAX_VALUE));
  background(240);
  noFill();

  let theta0 = random(TWO_PI);
  for (let j = 0; j < 5; j++) {
    background(240, 75);

    for(let i = 0; i < 20; i++) {
      // random height, bigger for foreground
      let h = random(map(j, 0, 5, 20, 50), map(j, 0, 5, 50, 150));
      let x = random(width);

      let y0 = 0.67*height + 10*j; // reference y pos, lower for foreground
      let s = sin(theta0 + 0.01*x); // sin for a curve
      let n = noise(0.01*x, j); // noise for some randomness
      let a = map(j, 0, 5, 70, 30); // amplitude, smaller for foreground
      let y = y0 + a*s*n;

      pine(x, y, h/2, h);
    }
  }
}

function pine(x, y, w, h) {
  var y0 = y - h;

  stroke(0, 10, 0);
  noFill();

  strokeWeight(2);
  line(x, y, x, y - h);

  strokeWeight(1.5);
  let di = random(3, 7);
  for (let i = y0; i < y; i += (Math.max(0.001, Math.abs(di)) || 1)) {
    let l = map(i, y0, y, 0, w);
    branch(x, i, l);
  }
}

function branch(x, y, l) {
  for (let i = 0; i < 10; i++) {
    let dy = random(-1, 5);
    let dl = random(1);
    bezier(x - dl*0.50*l, y + dy,
           x - dl*0.25*l, y,
           x + dl*0.25*l, y,
           x + dl*0.50*l, y + dy);
  }
}
